/* =====================================================================
 * SETTING CONTROLS
 * Every slider-backed setting is one entry in SLIDERS. setSetting()
 * clamps the value, stores it, updates the slider and readout, then
 * runs the entry's onChange to apply it.
 * ===================================================================== */

import { CONFIG } from "../config.js";
import { barLength, beatLength, eqGains, player, settings } from "../context.js";
import { stepSizes } from "../core/beats.js";
import { clamp, formatFrequency, formatGain, formatPercent, formatSigned, formatSpeed } from "../core/format.js";
import {
  $,
  dom,
  renderBeatInfo,
  element,
  guarded,
  onClick,
  renderEqEnabled,
  renderPitchTotal,
  renderSpeedChips,
  renderStepSize,
  speedChips,
} from "./dom.js";

/* ---------- Generated controls ---------- */

export function buildSpeedChips() {
  for (const speed of CONFIG.speed.presets) {
    const chip = element("button", { type: "button", className: "chip" }, `${speed}×`);
    chip.dataset.speed = speed;
    dom.speedChips.append(chip);
  }
}

// The labels under the speed and volume sliders, from CONFIG.
export function buildScales() {
  const { speed, volume } = CONFIG;
  dom.speedScale.append(element("span", {}, `${speed.min}×`), element("span", {}, `${speed.max}×`));
  for (const percent of [volume.min, CONFIG.volume.initial, volume.max]) {
    dom.volumeScale.append(element("span", {}, formatPercent(percent)));
  }
}

export function buildEqFaders() {
  for (const band of CONFIG.eq.bands) {
    dom.eqFaders.append(
      element(
        "div",
        { className: "fader" },
        element("output", { id: `${band.id}Value` }),
        element("input", { id: band.id, type: "range" }),
        element("label", { htmlFor: band.id }, band.label, element("small", {}, formatFrequency(band.frequency))),
      ),
    );
  }
}

/* ---------- Sliders and settings ---------- */

function applyEq() {
  player.engine.setEq(eqGains(), settings.eqEnabled);
}

function applyPitch() {
  renderPitchTotal();
  player.transport.retune();
}

/**
 * A setting controlled by a range input (see SLIDERS).
 * @typedef {object} SliderSpec
 * @property {string} inputId The <input type="range">.
 * @property {string} readoutId The element showing the formatted value.
 * @property {{ min: number, max: number, step: number, initial: number }} range From CONFIG.
 * @property {(value: number) => string} format
 * @property {() => void} onChange Applies the new value (audio, other UI).
 */

/** @type {Record<string, SliderSpec>} */
const SLIDERS = {
  speed: {
    inputId: "speed",
    readoutId: "speedValue",
    range: CONFIG.speed,
    format: formatSpeed,
    onChange: () => {
      renderSpeedChips();
      renderBeatInfo(); // the tempo heard
      player.transport.retune();
    },
  },
  volume: {
    inputId: "volume",
    readoutId: "volumeValue",
    range: CONFIG.volume,
    format: formatPercent,
    onChange: () => player.engine.setVolume(settings.volume / 100),
  },
  semitones: {
    inputId: "semitoneShift",
    readoutId: "semitoneValue",
    range: CONFIG.semitones,
    format: (value) => formatSigned(value, " st"),
    onChange: applyPitch,
  },
  cents: {
    inputId: "centShift",
    readoutId: "centValue",
    range: CONFIG.cents,
    format: (value) => formatSigned(value, " ct"),
    onChange: applyPitch,
  },
  // One per EQ band; the faders themselves are generated by buildEqFaders().
  ...Object.fromEntries(
    CONFIG.eq.bands.map((band) => [
      band.id,
      { inputId: band.id, readoutId: `${band.id}Value`, range: CONFIG.eq.gain, format: formatGain, onChange: applyEq },
    ]),
  ),
};

const sliderInput = (slider) => /** @type {HTMLInputElement} */ ($(slider.inputId));

/**
 * @param {string} key A key of SLIDERS (and of `settings`).
 * @param {number | string} value Clamped to the slider's range.
 */
export function setSetting(key, value) {
  const slider = SLIDERS[key];
  const { min, max } = slider.range;

  settings[key] = clamp(Number(value), min, max);
  sliderInput(slider).value = String(settings[key]);
  $(slider.readoutId).textContent = slider.format(settings[key]);
  slider.onChange();
}

export function setEqEnabled(enabled) {
  settings.eqEnabled = enabled;
  renderEqEnabled();
  applyEq();
}

function resetPitch() {
  setSetting("semitones", CONFIG.semitones.initial);
  setSetting("cents", CONFIG.cents.initial);
}

// Back to the defaults for everything that shapes the sound: speed, pitch,
// volume and EQ (gains and on/off). The step size is how you move around,
// not how it sounds, so it stays.
export function resetSoundSettings() {
  for (const [key, slider] of Object.entries(SLIDERS)) setSetting(key, slider.range.initial);
  setEqEnabled(CONFIG.eq.enabledInitially);
}

function resetEq() {
  for (const band of CONFIG.eq.bands) setSetting(band.id, CONFIG.eq.gain.initial);
}

// The step sizes in order: CONFIG.step.sizes, and "beat" and "bar" among
// them by their lengths while the track's beats (and downbeats) are known.
const currentStepSizes = () => stepSizes(CONFIG.step.sizes, { beat: beatLength(), bar: barLength() });

// ↑ / ↓: the next larger (+1) or smaller (−1) step size; stops at either end.
export function changeStepSize(direction) {
  const sizes = currentStepSizes();
  const index = sizes.indexOf(settings.stepSize);
  setStepSize(sizes[clamp(index + direction, 0, sizes.length - 1)]);
}

// Shift+, / Shift+.: the speed down (−1) or up (+1) by CONFIG.speed.nudge.
// Rounded to it, so steps land exactly on the presets (renderSpeedChips
// compares with ===).
export function nudgeSpeed(direction) {
  const { nudge } = CONFIG.speed;
  const steps = Math.round(settings.speed / nudge) + direction;
  setSetting("speed", Number((steps * nudge).toFixed(10)));
}

// A click on the step size: the next larger (+1) or smaller (−1) one,
// going round from either end.
export function cycleStepSize(direction) {
  const sizes = currentStepSizes();
  const index = sizes.indexOf(settings.stepSize);
  setStepSize(sizes[(index + direction + sizes.length) % sizes.length]);
}

/**
 * One of CONFIG.step.sizes, or "beat" / "bar" while there are beats /
 * downbeats (anything else is ignored).
 * @param {number | "beat" | "bar"} size
 */
export function setStepSize(size) {
  const allowed =
    size === "beat" ? beatLength() !== null : size === "bar" ? barLength() !== null : CONFIG.step.sizes.includes(size);
  if (!allowed) return;
  settings.stepSize = size;
  renderStepSize();
}

// Gives each slider its range from CONFIG, shows the current value and
// listens for input.
export function initSliders() {
  for (const [key, slider] of Object.entries(SLIDERS)) {
    const input = sliderInput(slider);
    const { min, max, step } = slider.range;
    Object.assign(input, { min: String(min), max: String(max), step: String(step) });

    setSetting(key, settings[key]);
    input.addEventListener(
      "input",
      guarded(() => setSetting(key, input.value)),
    );
  }
}

// The speed chips, Reset buttons and EQ on/off.
export function bindSettingControls() {
  for (const chip of speedChips()) {
    onClick(chip, () => setSetting("speed", chip.dataset.speed));
  }

  onClick(dom.resetPitchButton, resetPitch);
  onClick(dom.resetEqButton, resetEq);
  onClick(dom.eqToggle, () => setEqEnabled(!settings.eqEnabled));
}
